using namespace std;
struct Pt{int x,y;bool operator<(Pt const&o)const{return tie(x,y)<tie(o.x,o.y);}bool operator==(Pt const&o)const{return x==o.x&&y==o.y;}};
long long cross(Pt a,Pt b,Pt c){return 1LL*(b.x-a.x)*(c.y-a.y)-1LL*(b.y-a.y)*(c.x-a.x);}
pair<int,int> dir(Pt a,Pt b){int dx=b.x-a.x,dy=b.y-a.y;int g=gcd(abs(dx),abs(dy));dx/=g;dy/=g;if(dx<0||(dx==0&&dy<0)){dx=-dx;dy=-dy;}return {dx,dy};}
struct Solver{int n;vector<array<int,3>>e;vector<char>s;int best;bool hit(array<int,3> const&x){return s[x[0]]||s[x[1]]||s[x[2]];}int lb(vector<int>const&u){vector<char>z(n);int c=0;for(int i:u){auto x=e[i];if(!z[x[0]]&&!z[x[1]]&&!z[x[2]]){for(int v:x)z[v]=1;c++;}}return c;}void dfs(int c){if(c>=best)return;vector<int>u,f(n);for(int i=0;i<(int)e.size();i++)if(!hit(e[i])){u.push_back(i);for(int v:e[i])f[v]++;}if(u.empty()){best=c;return;}if(c+lb(u)>=best)return;int q=u[0],sc=-1;for(int i:u){int t=0;for(int v:e[i])t+=f[v];if(t>sc)sc=t,q=i;}auto b=e[q];sort(b.begin(),b.end(),[&](int a,int b){return f[a]>f[b];});for(int v:b){s[v]=1;dfs(c+1);s[v]=0;}}int minimum(int ub){s.assign(n,0);best=ub;dfs(0);return best;}void en(int t,set<vector<int>>&o,int c=0){if(c>t)return;vector<int>u,f(n);for(int i=0;i<(int)e.size();i++)if(!hit(e[i])){u.push_back(i);for(int v:e[i])f[v]++;}if(u.empty()){if(c==t){vector<int>x;for(int i=0;i<n;i++)if(s[i])x.push_back(i);o.insert(x);}return;}if(c+lb(u)>t)return;int q=u[0],sc=-1;for(int i:u){int z=0;for(int v:e[i])z+=f[v];if(z>sc)sc=z,q=i;}auto b=e[q];sort(b.begin(),b.end(),[&](int a,int b){return f[a]>f[b];});for(int v:b){s[v]=1;en(t,o,c+1);s[v]=0;}}};
bool refill(const vector<Pt>&orig,const vector<Pt>&del,vector<Pt>&ans){set<Pt>D(del.begin(),del.end());vector<Pt>b;for(auto p:orig)if(!D.count(p))b.push_back(p);sort(b.begin(),b.end());map<int,int>cc,rr;for(auto p:del)cc[p.x]++,rr[p.y]++;vector<int>cols;for(auto [x,n]:cc)while(n--)cols.push_back(x);map<int,vector<int>>cand;for(auto [x,n]:cc){for(auto [y,m]:rr){Pt p{x,y};if(binary_search(b.begin(),b.end(),p))continue;set<pair<int,int>>ds;bool ok=1;for(auto q:b)if(!ds.insert(dir(p,q)).second){ok=0;break;}if(ok)cand[x].push_back(y);}if((int)cand[x].size()<n)return false;}vector<Pt>ch;map<int,int>rem=rr;function<bool(int)>go=[&](int i){if(i==(int)cols.size()){ans=ch;sort(ans.begin(),ans.end());return true;}int x=cols[i],prev=-1000000000;if(i&&cols[i-1]==x)prev=ch.back().y;for(int y:cand[x]){if(y<=prev||!rem[y])continue;Pt p{x,y};bool bad=0;for(auto s:ch){for(auto q:b)if(cross(q,s,p)==0){bad=1;break;}if(bad)break;}for(int a=0;a<(int)ch.size()&&!bad;a++)for(int d=a+1;d<(int)ch.size();d++)if(cross(ch[a],ch[d],p)==0){bad=1;break;}if(bad)continue;rem[y]--;ch.push_back(p);if(go(i+1))return true;ch.pop_back();rem[y]++;}return false;};return go(0);}
int main(){
vector<Pt>T={{0,110},{0,196},{1,61},{1,113},{2,98},{2,257},{3,3},{3,100},{4,33},{4,77},{5,1},{5,35},{6,2},{6,33},{7,32},{7,35},{8,34},{8,105},{9,60},{9,349},{10,58},{10,61},{11,59},{11,60},{12,2},{12,105},{13,46},{13,77},{14,47},{14,258},{15,46},{15,49},{16,75},{16,76},{17,74},{17,99},{18,76},{18,316},{19,0},{19,346},{20,106},{20,107},{21,0},{21,108},{22,107},{22,315},{23,58},{23,195},{24,82},{24,110},{25,80},{25,81},{26,47},{26,48},{27,80},{27,81},{28,3},{28,108},{29,111},{29,112},{30,49},{30,113},{31,111},{31,112},{32,98},{32,258},{33,99},{33,101},{34,32},{34,101},{35,82},{35,100},{36,163},{36,164},{37,162},{37,165},{38,163},{38,164},{39,162},{39,312},{40,34},{40,315},{41,194},{41,195},{42,193},{42,196},{43,79},{43,194},{44,260},{44,377},{45,257},{45,259},{46,1},{46,259},{47,48},{47,260},{48,165},{48,313},{49,314},{49,316},{50,193},{50,314},{51,75},{51,313},{52,79},{52,379},{53,376},{53,378},{54,376},{54,378},{55,377},{55,379},{56,346},{56,348},{57,347},{57,349},{58,74},{58,347},{59,59},{59,348},{60,309},{60,312},{61,310},{61,311},{62,106},{62,309},{63,310},{63,311}};sort(T.begin(),T.end());
vector<Pt>P2={{0,1},{0,3},{1,0},{1,2},{2,0},{2,2},{3,1},{3,3}},block;for(auto p:P2)block.push_back({64+p.x,252+p.y});vector<Pt>all=T;all.insert(all.end(),block.begin(),block.end());sort(all.begin(),all.end());all.erase(unique(all.begin(),all.end()),all.end());auto loc=[&](Pt p){return int(lower_bound(all.begin(),all.end(),p)-all.begin());};set<array<int,3>>es;for(int i=0;i<(int)T.size();i++)for(int j=i+1;j<(int)T.size();j++)for(auto c:block)if(cross(T[i],T[j],c)==0){array<int,3>x={loc(T[i]),loc(T[j]),loc(c)};sort(x.begin(),x.end());es.insert(x);}for(int i=0;i<(int)block.size();i++)for(int j=i+1;j<(int)block.size();j++)for(auto c:T)if(cross(block[i],block[j],c)==0){array<int,3>x={loc(block[i]),loc(block[j]),loc(c)};sort(x.begin(),x.end());es.insert(x);}Solver s;s.n=all.size();s.e.assign(es.begin(),es.end());int m=s.minimum(9);set<vector<int>>cores;s.s.assign(s.n,0);s.en(m,cores);cerr<<"m="<<m<<" triples="<<es.size()<<" cores="<<cores.size()<<"\n";int ci=0;map<int,int>hist;for(auto I:cores){ci++;vector<Pt>core;set<int>S(I.begin(),I.end());for(int i:I)core.push_back(all[i]);vector<Pt>avail;for(int i=0;i<(int)all.size();i++)if(!S.count(i))avail.push_back(all[i]);bool ok=0;for(int budget=m;budget<=7&&!ok;budget++){int ex=budget-m;vector<Pt>bd,ba;auto tr=[&](vector<Pt>d){vector<Pt>a;if(refill(all,d,a)){bd=d;ba=a;return true;}return false;};if(ex==0)ok=tr(core);else if(ex==1)for(int a=0;a<(int)avail.size()&&!ok;a++){auto d=core;d.push_back(avail[a]);ok=tr(d);}else if(ex==2)for(int a=0;a<(int)avail.size()&&!ok;a++)for(int b=a+1;b<(int)avail.size()&&!ok;b++){auto d=core;d.push_back(avail[a]);d.push_back(avail[b]);ok=tr(d);}else if(ex==3)for(int a=0;a<(int)avail.size()&&!ok;a++)for(int b=a+1;b<(int)avail.size()&&!ok;b++)for(int c=b+1;c<(int)avail.size()&&!ok;c++){auto d=core;d.push_back(avail[a]);d.push_back(avail[b]);d.push_back(avail[c]);ok=tr(d);}else if(ex==4)for(int a=0;a<(int)avail.size()&&!ok;a++)for(int b=a+1;b<(int)avail.size()&&!ok;b++)for(int c=b+1;c<(int)avail.size()&&!ok;c++)for(int d=c+1;d<(int)avail.size()&&!ok;d++){auto z=core;z.push_back(avail[a]);z.push_back(avail[b]);z.push_back(avail[c]);z.push_back(avail[d]);ok=tr(z);}if(ok){hist[budget]++;cout<<"core "<<ci<<" budget "<<budget<<"\nD";sort(bd.begin(),bd.end());sort(ba.begin(),ba.end());for(auto p:bd)cout<<" ("<<p.x<<","<<p.y<<")";cout<<"\nA";for(auto p:ba)cout<<" ("<<p.x<<","<<p.y<<")";cout<<"\n";}}
if(!ok)cout<<"core "<<ci<<" FAIL\n";}int sc=0;for(auto [k,v]:hist)sc+=v;cerr<<"attempts=1 totalcores="<<cores.size()<<" successful_cores="<<sc<<" budgets";for(auto [k,v]:hist)cerr<<" "<<k<<":"<<v;cerr<<"\n";
}
